CREATE POLICY "avatar_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR private.has_role(auth.uid(), 'admin')));
CREATE POLICY "avatar_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "avatar_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR private.has_role(auth.uid(), 'admin'))) WITH CHECK (bucket_id = 'avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR private.has_role(auth.uid(), 'admin')));
CREATE POLICY "avatar_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatars' AND ((storage.foldername(name))[1] = auth.uid()::text OR private.has_role(auth.uid(), 'admin')));
CREATE POLICY "deliverable_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'deliverables' AND EXISTS (SELECT 1 FROM public.deliverables d JOIN public.projects p ON p.id=d.project_id JOIN public.clients c ON c.id=p.client_id WHERE d.file_path=name AND (c.user_id=auth.uid() OR private.has_role(auth.uid(),'admin'))));
CREATE POLICY "deliverable_admin_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'deliverables' AND private.has_role(auth.uid(),'admin'));
CREATE POLICY "deliverable_admin_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'deliverables' AND private.has_role(auth.uid(),'admin')) WITH CHECK (bucket_id = 'deliverables' AND private.has_role(auth.uid(),'admin'));
CREATE POLICY "deliverable_admin_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'deliverables' AND private.has_role(auth.uid(),'admin'));